import { Component, computed, signal } from '@angular/core';

@Component({
  selector: 'app-cart',
  template: `
    <p>{{ count() }} items, total {{ total() }}</p>
    <button (click)="add(25)">Add 25</button>
    <button (click)="clear()">Clear</button>
  `,
})
export class Cart {
  readonly prices = signal<number[]>([10, 15]);
  readonly count = computed(() => this.prices().length);
  readonly total = computed(() => this.prices().reduce((sum, p) => sum + p, 0));

  add(price: number): void {
    this.prices.update((list) => [...list, price]);
  }

  clear(): void {
    this.prices.set([]);
  }
}

import { Component, effect, signal } from '@angular/core';

@Component({
  selector: 'app-theme-switch',
  template: `<button (click)="toggle()">Switch to {{ theme() === 'light' ? 'dark' : 'light' }}</button>`,
})
export class ThemeSwitch {
  readonly theme = signal<'light' | 'dark'>('light');

  constructor() {
    effect(() => {
      document.body.dataset['theme'] = this.theme();
      console.log(`theme is now ${this.theme()}`);
    });
  }

  toggle(): void {
    this.theme.update((t) => (t === 'light' ? 'dark' : 'light'));
  }
}

import { Component, linkedSignal, signal } from '@angular/core';

@Component({
  selector: 'app-shipping',
  template: `
    @for (option of options(); track option) {
      <button (click)="selected.set(option)">{{ option }}</button>
    }
    <p>Selected: {{ selected() }}</p>
    <button (click)="reload()">Reload options</button>
  `,
})
export class Shipping {
  readonly options = signal(['Standard', 'Express']);
  readonly selected = linkedSignal(() => this.options()[0]);

  reload(): void {
    this.options.set(['Pickup', 'Courier']);
  }
}
